using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BatchPavingPolishReview{static BatchPavingPolishReview(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("BatchPavingPolishReview.request"))return;File.Delete("BatchPavingPolishReview.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BatchPavingPolish.txt",e.ToString());Debug.LogException(e);}}static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=sc.GetRootGameObjects();var map=roots.Single(g=>g.name=="Track Roads").GetComponent<CityGroundTextureLayout>();if(ShaderUtil.ShaderHasError(map.plots[0].renderer.sharedMaterial.shader))throw new Exception("Ground shader error");var ctrl=roots.SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyDay();map.Apply();var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);foreach(var name in new[]{"polySurface749","polySurface744","Line001"}){var p=map.plots.Single(t=>t.renderer.name==name);var c=p.renderer.bounds.center;var tr=p.patches[0];var tc=new Vector3(tr.x,c.y,tr.y);var n=(tc-c).normalized;n.y=0;if(n.sqrMagnitude<.1)n=Vector3.right;cap.Invoke(null,new object[]{sc,tc+n*24+Vector3.up*15,tc-n*4+Vector3.up*2,"Paving-Polished-"+name});if(name=="polySurface749"){var q=tc+new Vector3(4.2f,0,2.5f);cap.Invoke(null,new object[]{sc,q+n*6+Vector3.up*3,q,"Paving-Polished-Close"});}}}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();map.Apply();}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/BatchPavingPolish.txt","SUCCESS paving finish refined across shared block layouts: restrained per-stone variation, more grain, anti-aliased joints and bevels, individual charcoal border stone joints. Existing layout records unchanged; no geometry, UV, material or texture assets added. Shader errors=False. Day/night state restored.");File.WriteAllText("CityGroundTextureVerify.request","run");}}